#!/usr/bin/env bash
# Step 7: fresh kernel replay. `leanchecker --fresh Main` starts from an empty
# environment and re-adds every declaration that Main depends on (Lean core,
# Batteries, the mathlib cache and the whole project) through the kernel.
# This removes trust in the .olean files: the build's own output, and mathlib's
# CI-built cache from step 4.
#
# Run it detached:  scripts/tools/in-tmux.sh scripts/07-kernel-replay.sh
# Do not edit this file while it runs (bash reads scripts incrementally).
#
# leanchecker is single-threaded and prints no progress. For an estimate, run in another
# terminal:  python3 -I scripts/tools/replay_progress.py $(pgrep -x leanchecker) $OUT/replay-progress.csv
# It records the share of .olean pages the replay has touched; it ended at ~96% here,
# because the kernel never needs some of the stored data.
# Measured on 32 Graviton4 cores / 61 GiB RAM + 64 GiB swap: 13 h 15 min wall clock,
# 48.5 GB peak RSS (mostly file-backed .olean pages; ~16 GB anonymous), no swap used.
# Outputs: $OUT/replay.log, $OUT/replay-monitor.csv
source "$(dirname "$0")/lib.sh"
need_toolchain
need_project
need_max_map_count
log_to 07-kernel-replay.log

[[ -d "$PROJ/.lake/build/lib" ]] || die "project not built; run scripts/05-build.sh"
target="${REPLAY_TARGET:-Main}"

start_monitor "$OUT/replay-monitor.csv" 300
trap stop_monitor EXIT
log "leanchecker --fresh $target"
# On Ctrl-C/TERM, Lake (in the same process group) stops; this script must carry on
# and still write its summary and exit status instead of dying with it.
trap 'echo "[interrupted; finishing up]"' INT TERM
start=$(date -u +%s)
set +e
(cd "$PROJ" && /usr/bin/time -v lake --keep-toolchain env leanchecker --fresh --verbose "$target") > "$OUT/replay.log" 2>&1
rc=$?
set -e
dur=$(( $(date -u +%s) - start ))
stop_monitor

tail -30 "$OUT/replay.log"
printf '\nduration %dh %02dm, exit %d\n' $((dur / 3600)) $((dur % 3600 / 60)) "$rc"
if (( rc == 0 )); then ok "kernel replay of $target from scratch succeeded"; else bad "kernel replay failed (exit $rc)"; fi
finish
